import SwiftUI
import KachiiroCore

/// A lookup, not a wall of rows: pick a form and see every chart verb in it, grouped by verb group;
/// or see each word type across the plain/polite matrix. Generated by the engines.
struct ConjugationReferenceView: View {
    enum Content { case verbChart, matrix, both }

    enum Tab: String, CaseIterable { case forms = "Verb forms", matrix = "Plain ↔ Polite" }

    var content: Content = .both
    /// Narrow layout for the iPad reference column.
    var compact = false
    /// The form a drill is asking about; the chart follows it.
    var focusForm: VerbForm?

    @State private var tab: Tab = .forms
    @State private var form: VerbForm = .te
    @State private var search = ""

    private var showsForms: Bool { content == .verbChart || (content == .both && tab == .forms) }

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 14) {
                if content == .both {
                    Picker("Table", selection: $tab) {
                        ForEach(Tab.allCases, id: \.self) { Text($0.rawValue).tag($0) }
                    }
                    .pickerStyle(.segmented)
                }
                if showsForms {
                    searchField
                    formChips
                    ForEach(groups, id: \.number) { group in
                        groupCard(number: group.number, title: group.title, tint: group.tint, verbs: group.verbs)
                    }
                    if filteredVerbs.isEmpty {
                        Text("No chart verb matches “\(search)”.")
                            .font(AppTheme.Fonts.ui(.subheadline))
                            .foregroundStyle(AppTheme.secondaryInk)
                    }
                } else {
                    ForEach(ConjugationReference.matrixLexemes, id: \.title) { row in matrixCard(row.title, row.lexeme) }
                }
            }
            .padding(compact ? 0 : 20)
            .padding(.vertical, compact ? 4 : 0)
            .frame(maxWidth: 720, alignment: .leading)
            .frame(maxWidth: .infinity)
        }
        .background(compact ? Color.clear : AppTheme.canvas)
        .onAppear { if let focusForm { form = focusForm } }
        .onChange(of: focusForm) { if let focusForm { form = focusForm } }
    }

    // MARK: Verb forms

    private var searchField: some View {
        HStack(spacing: 8) {
            Image(systemName: "magnifyingglass").foregroundStyle(AppTheme.secondaryInk).accessibilityHidden(true)
            TextField("Search a chart verb, e.g. よむ", text: $search)
                .textInputAutocapitalization(.never)
                .autocorrectionDisabled()
        }
        .font(AppTheme.Fonts.ui(.body))
        .padding(.horizontal, 12)
        .frame(minHeight: 44)
        .background(AppTheme.cardSurface, in: RoundedRectangle(cornerRadius: 14, style: .continuous))
    }

    private var formChips: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 6) {
                ForEach(VerbForm.allCases, id: \.self) { item in
                    let selected = item == form
                    Button { form = item } label: {
                        Text(item.shortLabel)
                            .font(.system(size: 15, weight: .bold))
                            .foregroundStyle(selected ? Color.white : AppTheme.primaryInk)
                            .padding(.horizontal, 12)
                            .frame(minHeight: 36)
                            .background(selected ? AppTheme.kachiiro : AppTheme.cardSurface, in: Capsule())
                    }
                    .buttonStyle(.plain)
                    .accessibilityLabel(item.label)
                    .accessibilityAddTraits(selected ? .isSelected : [])
                }
            }
        }
    }

    private var filteredVerbs: [Lexeme] {
        let query = search.trimmingCharacters(in: .whitespaces)
        guard !query.isEmpty else { return ConjugationReference.verbs }
        return ConjugationReference.verbs.filter { $0.headword.contains(query) || $0.reading.contains(query) }
    }

    private var groups: [(number: Int, title: String, tint: Color, verbs: [Lexeme])] {
        let verbs = filteredVerbs
        return [
            (1, "Group 1 · う-verbs", AppTheme.accent, verbs.filter { $0.kind == .godan }),
            (2, "Group 2 · る-verbs", Color(hex: 0x5AA2F0), verbs.filter { $0.kind == .ichidan }),
            (3, "Group 3 · irregular", AppTheme.kachiiro, verbs.filter { $0.kind == .suruKuru }),
        ].filter { !$0.verbs.isEmpty }
    }

    private func groupCard(number: Int, title: String, tint: Color, verbs: [Lexeme]) -> some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: 10) {
                Text("\(number)")
                    .font(AppTheme.Fonts.ui(.subheadline, weight: .heavy))
                    .foregroundStyle(.white)
                    .frame(width: 28, height: 28)
                    .background(tint, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                    .accessibilityHidden(true)
                Text(title).font(AppTheme.Fonts.ui(.subheadline, weight: .heavy))
                Spacer()
                Text(compact ? "\(form.shortLabel)形" : form.label)
                    .font(AppTheme.Fonts.ui(.caption, weight: .semibold))
                    .foregroundStyle(AppTheme.secondaryInk)
                    .lineLimit(1)
            }
            .padding(.vertical, 10)
            .accessibilityElement(children: .combine)
            .accessibilityAddTraits(.isHeader)
            ForEach(verbs, id: \.headword) { verb in
                Divider().overlay(AppTheme.hairlineBorder)
                HStack {
                    Text(verb.headword).font(.system(size: 17)).foregroundStyle(AppTheme.secondaryInk)
                    Image(systemName: "arrow.right").font(.caption.weight(.bold)).foregroundStyle(AppTheme.tertiaryInk)
                        .accessibilityHidden(true)
                    Spacer()
                    Text(KatsuyouEngine.conjugate(verb, form: form)?.display ?? "–")
                        .font(.system(size: 19, weight: .bold))
                        .foregroundStyle(AppTheme.primaryInk)
                }
                .padding(.vertical, 9)
                .accessibilityElement(children: .combine)
            }
        }
        .foregroundStyle(AppTheme.primaryInk)
        .padding(.horizontal, 14)
        .padding(.bottom, 4)
        .background(AppTheme.cardSurface, in: RoundedRectangle(cornerRadius: AppTheme.Radius.card, style: .continuous))
    }

    // MARK: Matrix

    private func matrixCard(_ title: String, _ lexeme: Lexeme) -> some View {
        let cells = InflectionCell.all
        let values = ConjugationReference.matrixRow(lexeme)
        let value = { (cell: InflectionCell) in values[cells.firstIndex(of: cell) ?? 0] }
        let rows: [(String, Tense, Polarity)] = [
            ("Non-past +", .nonPast, .affirmative), ("Non-past −", .nonPast, .negative),
            ("Past +", .past, .affirmative), ("Past −", .past, .negative),
        ]
        return VStack(alignment: .leading, spacing: 10) {
            HStack(alignment: .firstTextBaseline) {
                Text(lexeme.headword).font(.system(size: 22, weight: .bold))
                Text(title).font(AppTheme.Fonts.ui(.caption, weight: .heavy)).foregroundStyle(AppTheme.accentText)
            }
            Grid(alignment: .leading, horizontalSpacing: 8, verticalSpacing: 6) {
                GridRow {
                    Text("")
                    Text("POLITE").font(AppTheme.Fonts.ui(.caption2, weight: .heavy)).foregroundStyle(AppTheme.secondaryInk)
                    Text("PLAIN").font(AppTheme.Fonts.ui(.caption2, weight: .heavy)).foregroundStyle(AppTheme.secondaryInk)
                }
                ForEach(rows, id: \.0) { label, tense, polarity in
                    GridRow {
                        Text(label)
                            .font(AppTheme.Fonts.ui(.caption, weight: .semibold))
                            .foregroundStyle(AppTheme.secondaryInk)
                            .fixedSize()
                        cell(value(InflectionCell(politeness: .polite, tense: tense, polarity: polarity)))
                        cell(value(InflectionCell(politeness: .plain, tense: tense, polarity: polarity)))
                    }
                }
            }
        }
        .foregroundStyle(AppTheme.primaryInk)
        .padding(14)
        .background(AppTheme.cardSurface, in: RoundedRectangle(cornerRadius: AppTheme.Radius.card, style: .continuous))
    }

    private func cell(_ text: String) -> some View {
        Text(text)
            .font(.system(size: 15, weight: .semibold))
            .minimumScaleFactor(0.7)
            .lineLimit(1)
            .frame(maxWidth: .infinity, minHeight: 36)
            .background(AppTheme.accentSoftFill, in: RoundedRectangle(cornerRadius: 10, style: .continuous))
    }
}
